package com.ruoyi.metal.service;
import java.util.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import org.springframework.jdbc.core.*;import org.springframework.jdbc.support.*;import org.springframework.transaction.PlatformTransactionManager;
class SemiAutoReleaseServiceTest {
 static class F {
  JdbcTemplate j=mock(JdbcTemplate.class);Map<String,Object> e=new HashMap<>(Map.of("event_id",5L,"factory_id",1L,"work_order_id",2L,"generation",1L,"actor_id",9L,"status","PENDING"));
  Map<String,Object> w=new HashMap<>(Map.of("work_order_id",2L,"factory_id",1L,"completion_generation",1L,"status","COMPLETED","del_flag","0"));
  Map<String,Object> stock=new HashMap<>(Map.of("inventory_id",7L,"factory_id",1L,"origin_batch_id",8L,"category","SEMI","quantity",4L,"net_weight",new BigDecimal("40"),"ownership_status","NORMAL","specification","10cm","organization","客户"));
  Map<String,Object> source=new HashMap<>(Map.of("status","SETTLED","product_snapshot","{\"specification\":\"10cm\"}","customer","客户","item_id",20L,"sequence_no",1L));
  F(){stock.put("reference_id",3L);source.put("product_id",3L);source.put("factory_id",1L);when(j.queryForMap(anyString(),any(Object[].class))).thenAnswer(a->{String q=a.getArgument(0);return q.contains("FROM metal_work_order")?w:e;});when(j.queryForList(anyString(),any(Object[].class))).thenAnswer(a->{String q=a.getArgument(0);if(q.startsWith("SELECT factory_id"))return List.of(Map.of("factory_id",1L));if(q.startsWith("SELECT i.* FROM metal_inventory"))return List.of(stock);if(q.startsWith("SELECT sequence_no,process_id"))return List.of(Map.of("sequence_no",1L,"process_id",11L));if(q.startsWith("SELECT b.*"))return List.of(source);return List.of();});doAnswer(a->{((KeyHolder)a.getArgument(1)).getKeyList().add(Map.of("release_id",99L));return 1;}).when(j).update(any(PreparedStatementCreator.class),any(KeyHolder.class));}
  void run(){new SemiAutoReleaseService(j,mock(PlatformTransactionManager.class)).process(5);}
 }
 @Test void positiveReleaseDoesNotWritePhysicalStockLedger(){var f=new F();f.run();verify(f.j).update(contains("SET status=?,message=?"),eq("RELEASED"),anyString(),eq(5L));verify(f.j).update(any(PreparedStatementCreator.class),any(KeyHolder.class));verify(f.j,never()).update(contains("metal_stock_ledger"),any(Object[].class));}
 @Test void noResidualNeedsNoReleaseEvenWithSkippedHistory(){var f=new F();f.stock.put("quantity",0L);f.stock.put("net_weight",BigDecimal.ZERO);f.source.put("execution_snapshot","{\"processed\":[1,3],\"skipped\":[2]}");f.run();verify(f.j).update(contains("SET status=?,message=?"),eq("NO_BALANCE"),anyString(),eq(5L));verify(f.j,never()).update(any(PreparedStatementCreator.class),any(KeyHolder.class));}
 @Test void skippedResidualCannotPretendFullRoute(){var f=new F();f.source.put("execution_snapshot","{\"processed\":[1,3],\"skipped\":[2]}");f.run();verify(f.j).update(contains("SET status=?,message=?"),eq("REVIEW"),anyString(),eq(5L));verify(f.j,never()).update(any(PreparedStatementCreator.class),any(KeyHolder.class));}
 @Test void staleCompletionGenerationCancelsEvent(){var f=new F();f.w.put("completion_generation",2L);f.run();verify(f.j).update(contains("SET status=?,message=?"),eq("CANCELLED"),anyString(),eq(5L));verify(f.j,never()).update(any(PreparedStatementCreator.class),any(KeyHolder.class));}
 @Test void canceledAutomaticReleaseIsNotRecreated(){var f=new F();doReturn(List.of(Map.of("release_id",99L,"status","CANCELLED"))).when(f.j).queryForList("SELECT release_id,status FROM metal_semi_release WHERE auto_event_id=? AND inventory_id=?",5L,7L);f.run();verify(f.j,never()).update(any(PreparedStatementCreator.class),any(KeyHolder.class));}
 @Test void missingSavedRouteIsReview(){var f=new F();doReturn(List.of()).when(f.j).queryForList("SELECT sequence_no,process_id FROM metal_work_order_step WHERE item_id=? AND sequence_no<=? ORDER BY sequence_no",20L,1L);f.run();verify(f.j).update(contains("SET status=?,message=?"),eq("REVIEW"),anyString(),eq(5L));}
 @Test void inventoryProductMustMatchSourceSnapshot(){var f=new F();f.stock.put("reference_id",999L);f.run();verify(f.j).update(contains("SET status=?,message=?"),eq("REVIEW"),anyString(),eq(5L));}
 @Test void workerMustReadCommittedBalancesAfterLockWait()throws Exception{var service=new SemiAutoReleaseService(mock(JdbcTemplate.class),mock(PlatformTransactionManager.class));var field=SemiAutoReleaseService.class.getDeclaredField("tx");field.setAccessible(true);assertEquals(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED,((org.springframework.transaction.support.TransactionTemplate)field.get(service)).getIsolationLevel());}
}
